-- 1.12: owner-reviewed corrections of 14 published A1 stories (level ladder v1.4; review of 2026-10-08).
-- Stop if any affected published story or question differs from the reviewed 1.11 baseline: one guard row per story,
-- because D1 refuses an expression tree deeper than 100 (one CASE over all 14 stories was refused).
-- Update paragraphs only. Preserve story/question IDs, quiz answers, flags, drafts, history and dictionary preferences.
CREATE TABLE _a1_112_guard(ok INTEGER NOT NULL CHECK(ok=1));
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=1 AND title='Будинок моєї сім''ї' AND json(paragraphs_json)=json('["Наша сім''я живе в будинку біля парку. У будинку живуть мама, тато, мій брат і я. Мама працює в школі, тато в магазині, а брат ходить у дитячий садок. Уранці всі поспішають, але ввечері ми знову разом.","На першому поверсі є кухня і вітальня. На кухні мама часто готує суп, а у вітальні ми дивимося телевізор. Там стоїть диван, стіл і велика шафа. У шафі лежать книжки і настільні ігри. На другому поверсі є наші спальні.","Моя кімната невелика, але в ній є ліжко, стіл і книжки. У дворі тато ставить лавку, і влітку ми сидимо там разом. Брат грається з м''ячем, а я дивлюся на дерева. Наш дім простий, але рідний."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1) AND display_order=1 AND prompt='Де живе сім''я?' AND correct_answer='У будинку біля парку' AND json(wrong_answers_json)=json('["У машині","У школі","На пошті"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1) AND display_order=2 AND prompt='Хто живе в будинку?' AND correct_answer='Мама, тато, брат і я' AND json(wrong_answers_json)=json('["Тільки мама","Три друзі","Учитель і клас"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1) AND display_order=3 AND prompt='Де мама готує суп?' AND correct_answer='На кухні' AND json(wrong_answers_json)=json('["У дворі","У ванній","У бібліотеці"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1) AND display_order=4 AND prompt='Що є в кімнаті автора?' AND correct_answer='Ліжко, стіл і книжки' AND json(wrong_answers_json)=json('["Гойдалка","Авто","Пошта"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=1) AND display_order=5 AND prompt='Що тато ставить у дворі?' AND correct_answer='Лавку' AND json(wrong_answers_json)=json('["Шафу","Двері","Машину"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=2 AND title='Книги та іграшки' AND json(paragraphs_json)=json('["Мене звати Софійка, і я дуже люблю книги та іграшки. У моїй кімнаті є полиця з казками і велика коробка з іграшками. Я часто сиджу біля полиці після школи. Спочатку я вибираю книжку, а потім відкриваю коробку.","Щовечора я читаю коротку книжку з малюнками. Моя улюблена книжка розповідає про дівчинку і ліс. Я читаю її багато разів, бо добре знаю героїв. Іноді мама слухає мене і допомагає читати нові слова.","У коробці лежать кубики, лялька і маленька машина. З кубиків я будую будинок, а лялька живе в цьому будинку. Коли мама читає зі мною, я повторюю нові слова. Потім я граюся і вигадую маленьку історію. Іноді я записую ім''я героя на папері і малюю поруч маленький будинок."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2) AND display_order=1 AND prompt='Що любить Софійка?' AND correct_answer='Книги та іграшки' AND json(wrong_answers_json)=json('["Машини","Пошту","Спорт"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2) AND display_order=2 AND prompt='Де стоять казки?' AND correct_answer='На полиці' AND json(wrong_answers_json)=json('["У машині","У дворі","На столі вчителя"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2) AND display_order=3 AND prompt='Про що улюблена книжка?' AND correct_answer='Про дівчинку і ліс' AND json(wrong_answers_json)=json('["Про пошту","Про машину","Про собаку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2) AND display_order=4 AND prompt='Що Софійка будує з кубиків?' AND correct_answer='Будинок' AND json(wrong_answers_json)=json('["Місто","Машину","Школу"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=2) AND display_order=5 AND prompt='Де лежить маленька машина?' AND correct_answer='У коробці' AND json(wrong_answers_json)=json('["На ліжку","У саду","У сумці"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=3 AND title='Мій будинок' AND json(paragraphs_json)=json('["Я живу в невеликому будинку біля саду. У будинку є чотири кімнати: кухня, спальня, вітальня і ванна кімната. Біля дверей стоїть полиця для ключів і взуття. На кухні стоїть стіл і чотири стільці. Уранці ми снідаємо там разом і говоримо про день.","У вітальні стоїть диван, низький столик і годинник на стіні. На дивані лежить теплий плед. У моїй спальні є ліжко, шафа і лампа біля ліжка. На столі лежать книжка і телефон. Я люблю свій будинок, бо він теплий і спокійний. Увечері я читаю у вітальні, а мама п''є чай на кухні. На вихідних я прибираю кімнату і ставлю книжки на свою полицю."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3) AND display_order=1 AND prompt='Скільки кімнат має будинок?' AND correct_answer='Чотири' AND json(wrong_answers_json)=json('["Дві","Шість","Одна"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3) AND display_order=2 AND prompt='Що стоїть на кухні?' AND correct_answer='Стіл і стільці' AND json(wrong_answers_json)=json('["Ліжко","Диван","Велосипед"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3) AND display_order=3 AND prompt='Де стоїть диван?' AND correct_answer='У вітальні' AND json(wrong_answers_json)=json('["У ванній","У саду","На пошті"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3) AND display_order=4 AND prompt='Що є біля ліжка?' AND correct_answer='Лампа' AND json(wrong_answers_json)=json('["Машина","Гойдалка","Миска"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=3) AND display_order=5 AND prompt='Який будинок?' AND correct_answer='Теплий і спокійний' AND json(wrong_answers_json)=json('["Шумний і холодний","Старий і темний","Великий і порожній"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=4 AND title='Мій день' AND json(paragraphs_json)=json('["Уранці я прокидаюся і відкриваю вікно. У кімнаті стає свіжо і світло. Потім я вмиваюся і зачісуюся перед дзеркалом. На кухні я їм хліб із сиром і п''ю воду.","Після сніданку я йду до школи. У школі я читаю, пишу і слухаю вчителя. Після уроків я обідаю і роблю вправи. Потім я складаю книжки на стіл.","Увечері я гуляю біля дому. Потім я дивлюся мультфільм, а мама готує вечерю. Я вечеряю з родиною і мию свою тарілку. Потім я рано лягаю спати."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4) AND display_order=1 AND prompt='Що герой робить уранці?' AND correct_answer='Відкриває вікно' AND json(wrong_answers_json)=json('["Купує машину","Йде на пошту","Грає в м''яч"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4) AND display_order=2 AND prompt='Що герой їсть на сніданок?' AND correct_answer='Хліб і сир' AND json(wrong_answers_json)=json('["Суп","Морозиво","Рибу"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4) AND display_order=3 AND prompt='Куди герой йде після сніданку?' AND correct_answer='До школи' AND json(wrong_answers_json)=json('["До моря","До бабусі","В автосалон"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4) AND display_order=4 AND prompt='Що герой робить після уроків?' AND correct_answer='Обідає і робить вправи' AND json(wrong_answers_json)=json('["Купує квіти","Пише адресу","Їде в парк"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=4) AND display_order=5 AND prompt='Що герой дивиться ввечері?' AND correct_answer='Мультфільм' AND json(wrong_answers_json)=json('["Розклад","Карту","Квитанцію"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=7 AND title='Мої канікули' AND json(paragraphs_json)=json('["У мене починаються канікули, і я не йду до школи. Уранці я сплю довше, а потім повільно снідаю. Мама готує млинці, а я п''ю чай і дивлюся у вікно.","Удень я гуляю з друзями в парку. Там є гойдалка, лавка і велика доріжка. Ми граємо в м''яч, а потім купуємо морозиво.","Увечері я читаю книжку або допомагаю вдома. Я мию тарілки після обіду і складаю іграшки в коробку. У серпні ми їдемо до Одеси, тому я дуже чекаю цю поїздку. Я хочу бачити море і збирати мушлі на пляжі. На канікулах день довгий, і я маю більше часу для гри, читання та прогулянок."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7) AND display_order=1 AND prompt='Що починається у героя?' AND correct_answer='Канікули' AND json(wrong_answers_json)=json('["Уроки","Робота","Тест"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7) AND display_order=2 AND prompt='Що готує мама?' AND correct_answer='Млинці' AND json(wrong_answers_json)=json('["Суп","Пасту","Рибу"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7) AND display_order=3 AND prompt='Куди герой іде з друзями?' AND correct_answer='У парк' AND json(wrong_answers_json)=json('["На пошту","У бібліотеку","У гараж"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7) AND display_order=4 AND prompt='Що друзі купують?' AND correct_answer='Морозиво' AND json(wrong_answers_json)=json('["Марку","Машину","Шафу"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=7) AND display_order=5 AND prompt='Куди сім''я їде в серпні?' AND correct_answer='До Одеси' AND json(wrong_answers_json)=json('["До Києва","До школи","До магазину"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=9 AND title='Моя чудова родина' AND json(paragraphs_json)=json('["У мене є чудова родина. Моя мама добра і спокійна, вона готує сніданок і часто читає книжки. Мій тато веселий, він працює в офісі і любить музику.","У мене є сестра Ліза. Вона ходить до школи і любить малювати квіти. Ще у нас є дідусь. Він часто розповідає цікаві історії. У неділю він приходить до нас на обід.","Увечері ми сидимо разом на кухні. Ми п''ємо чай, говоримо про день і сміємося. Ліза показує малюнок, тато слухає, а мама усміхається. Я дуже люблю свою родину. Коли мені потрібна допомога, родина завжди поруч. Тому вдома мені легко і тепло."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9) AND display_order=1 AND prompt='Яка родина у героя?' AND correct_answer='Чудова' AND json(wrong_answers_json)=json('["Мала і сумна","Нова","Далека"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9) AND display_order=2 AND prompt='Що робить мама?' AND correct_answer='Готує сніданок і читає книжки' AND json(wrong_answers_json)=json('["Водить машину","Продає марки","Грає в шахи"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9) AND display_order=3 AND prompt='Як звати сестру?' AND correct_answer='Ліза' AND json(wrong_answers_json)=json('["Оля","Софійка","Марта"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9) AND display_order=4 AND prompt='Що любить Ліза?' AND correct_answer='Малювати квіти' AND json(wrong_answers_json)=json('["Купувати машини","Писати адресу","Годувати кота"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=9) AND display_order=5 AND prompt='Що сім''я робить увечері?' AND correct_answer='П''є чай і говорить' AND json(wrong_answers_json)=json('["Йде до школи","Купує корм","Їде до моря"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=10 AND title='На пошті' AND json(paragraphs_json)=json('["Сьогодні я йду на пошту, бо маю лист для тітки. Пошта стоїть біля магазину. Я кладу лист у сумку і беру адресу.","На пошті працює привітна жінка. У залі тихо, і переді мною стоїть тільки один чоловік. Вона питає адресу, і я читаю її з паперу. Потім жінка бере лист, дає марку, і я плачу гроші.","Після цього я беру квитанцію і кажу: Дякую. Біля пошти стоїть лавка, тому я сідаю на хвилину. Увечері я кажу мамі, що лист уже їде до тітки."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10) AND display_order=1 AND prompt='Куди йде герой?' AND correct_answer='На пошту' AND json(wrong_answers_json)=json('["До школи","У парк","В автосалон"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10) AND display_order=2 AND prompt='Для кого є лист?' AND correct_answer='Для тітки' AND json(wrong_answers_json)=json('["Для тата","Для вчителя","Для собаки"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10) AND display_order=3 AND prompt='Що питає жінка?' AND correct_answer='Адресу' AND json(wrong_answers_json)=json('["Розклад","Колір","Ім''я кота"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10) AND display_order=4 AND prompt='Що жінка дає?' AND correct_answer='Марку' AND json(wrong_answers_json)=json('["Квіти","Машину","Іграшку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=10) AND display_order=5 AND prompt='Що герой бере в кінці?' AND correct_answer='Квитанцію' AND json(wrong_answers_json)=json('["Ключ","Миску","Книжку"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=12 AND title='Новий однокласник' AND json(paragraphs_json)=json('["Сьогодні в наш клас приходить новий хлопець. Його звати Данило, і він сідає біля мене. Я кажу: Привіт, мене звати Оля. Данило усміхається і відповідає: Привіт, дуже приємно. Учитель просить нас показати Данилу розклад.","На перерві я питаю Данила, де він живе. Він каже, що живе біля парку. Потім ми говоримо про хобі. Данило любить футбол і шахи, а я люблю футбол і книжки.","Після уроків ми разом ідемо додому. Завтра ми знову сидимо поруч у класі. Він показує мені новий пенал, а я показую йому шкільний двір. Мені легко говорити з ним українською."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12) AND display_order=1 AND prompt='Як звати нового хлопця?' AND correct_answer='Данило' AND json(wrong_answers_json)=json('["Максим","Богдан","Рекс"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12) AND display_order=2 AND prompt='Хто знайомиться з Данилом?' AND correct_answer='Оля' AND json(wrong_answers_json)=json('["Ліза","Софійка","Мама"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12) AND display_order=3 AND prompt='Де живе Данило?' AND correct_answer='Біля парку' AND json(wrong_answers_json)=json('["Біля моря","На пошті","У гаражі"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12) AND display_order=4 AND prompt='Що любить Данило?' AND correct_answer='Футбол і шахи' AND json(wrong_answers_json)=json('["Молоко і чай","Квіти і суп","Пошту і марки"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=12) AND display_order=5 AND prompt='Куди діти йдуть після уроків?' AND correct_answer='Додому разом' AND json(wrong_answers_json)=json('["В автосалон","До бабусі","На море"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=13 AND title='Поїздка з мамою' AND json(paragraphs_json)=json('["Сьогодні я їду з мамою на машині до бабусі. Мама сидить за кермом, а я сиджу поруч і тримаю квіти. У машині грає тиха музика, тому дорога здається приємною. Мама питає мене про школу, і я розповідаю про уроки.","Ми їдемо через місто і бачимо магазин, аптеку та школу. Потім машина їде біля річки, і я дивлюся на воду. Мама питає, чи я взяв подарунок, і я показую квіти. Я також беру маленький пиріг у коробці.","Через двадцять хвилин ми приїжджаємо. Бабуся стоїть біля воріт і радіє нам. Я даю їй квіти, мама ставить сумку на стілець, і ми сідаємо за стіл."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13) AND display_order=1 AND prompt='З ким герой їде на машині?' AND correct_answer='З мамою' AND json(wrong_answers_json)=json('["З татом","З учителем","З другом"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13) AND display_order=2 AND prompt='Куди вони їдуть?' AND correct_answer='До бабусі' AND json(wrong_answers_json)=json('["До школи","На пошту","У бібліотеку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13) AND display_order=3 AND prompt='Що герой бере для бабусі?' AND correct_answer='Квіти' AND json(wrong_answers_json)=json('["Книжку","М''яч","Лист"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13) AND display_order=4 AND prompt='Що грає в машині?' AND correct_answer='Тиха музика' AND json(wrong_answers_json)=json('["Гучний фільм","Урок","Новини"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=13) AND display_order=5 AND prompt='Де стоїть бабуся?' AND correct_answer='Біля воріт' AND json(wrong_answers_json)=json('["Біля школи","У магазині","У парку"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=14 AND title='Розклад занять студента' AND json(paragraphs_json)=json('["Мене звати Максим, і я навчаюся в коледжі в Києві. У понеділок я встаю о сьомій годині, бо перше заняття починається о дев''ятій. Я беру зошит, ручку, книжку і йду до школи. Біля входу я зустрічаю друга Андрія. Ми разом ідемо в клас і дивимося розклад на дверях.","Після занять я заходжу в бібліотеку. Там тихо, тому я читаю текст і роблю домашнє завдання. У середу в мене українська мова і математика, а в четвер історія. У п''ятницю ми пишемо короткий тест. Увечері я готую сумку, перевіряю олівці і заряджаю телефон. Потім я трохи відпочиваю вдома."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14) AND display_order=1 AND prompt='Де навчається Максим?' AND correct_answer='У коледжі' AND json(wrong_answers_json)=json('["У лікарні","На пошті","У магазині"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14) AND display_order=2 AND prompt='Куди Максим йде після занять?' AND correct_answer='У бібліотеку' AND json(wrong_answers_json)=json('["У парк","На пошту","У магазин"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14) AND display_order=3 AND prompt='Що Максим бере на заняття?' AND correct_answer='Зошит, ручку і книжку' AND json(wrong_answers_json)=json('["М''яч і шапку","Ключі і квіти","Молоко і хліб"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14) AND display_order=4 AND prompt='Коли Максим має короткий тест?' AND correct_answer='У п''ятницю' AND json(wrong_answers_json)=json('["У неділю","У суботу","У понеділок"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=14) AND display_order=5 AND prompt='Що Максим робить увечері?' AND correct_answer='Готує сумку' AND json(wrong_answers_json)=json('["Пише тест","Іде в клас","Зустрічає друга"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=18 AND title='Сніданок удома' AND json(paragraphs_json)=json('["На кухні вже сидить моя сестра. Вона ставить на стіл дві тарілки і чашки. Я кладу на стіл хліб, сир і помідор. Сестра ріже хліб, а я мию помідор. Усе готове. Ми сідаємо біля вікна і бажаємо одна одній смачного.","Я їм хліб і сир та п''ю чай. Сестра теж п''є чай, але їсть помідор. За сніданком ми завжди слухаємо тиху музику. Потім я мию чашки і ставлю їх на полицю. Час іти. Я виходжу з кухні та беру сумку для роботи."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18) AND display_order=1 AND prompt='З ким снідає авторка?' AND correct_answer='Із сестрою' AND json(wrong_answers_json)=json('["З мамою","З братом","Із сусідкою"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18) AND display_order=2 AND prompt='Хто ріже хліб?' AND correct_answer='Сестра' AND json(wrong_answers_json)=json('["Мама","Бабуся","Тітка"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18) AND display_order=3 AND prompt='Що їсть авторка?' AND correct_answer='Хліб і сир' AND json(wrong_answers_json)=json('["Кашу з молоком","Яйце з огірком","Булку з маслом"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18) AND display_order=4 AND prompt='Що слухають за сніданком?' AND correct_answer='Тиху музику' AND json(wrong_answers_json)=json('["Ранкові новини","Коротку казку","Розмову про спорт"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=18) AND display_order=5 AND prompt='Що авторка робить після їжі?' AND correct_answer='Миє чашки' AND json(wrong_answers_json)=json('["Прибирає кімнату","Гуляє з собакою","Пише повідомлення"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=20 AND title='Погода сьогодні' AND json(paragraphs_json)=json('["Уранці сонце світить у вікна нашого маленького будинку. Сьогодні в місті тепло. З вікна будинку біля парку видно синє небо. Жінка повільно веде маленьку дівчинку до річки біля парку. На жінці теплий светр, а на дівчинці біла сорочка. Поруч хлопець повільно їде на велосипеді з великим рюкзаком.","Спочатку хлопець грає з друзями в м''яч біля річки. Жінка з дівчинкою сидить на лавці біля старого дерева. Після гри хлопець сідає біля річки і п''є воду. Велосипед стоїть поруч. Жінка з дівчинкою тепер дивиться на воду біля лавки. На воді світить сонце."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=1 AND prompt='Яке сьогодні небо?' AND correct_answer='Синє' AND json(wrong_answers_json)=json('["Сіре","Біле","Червоне"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=2 AND prompt='Кого веде жінка?' AND correct_answer='Дівчинку' AND json(wrong_answers_json)=json('["Хлопця","Бабусю","Друга"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=3 AND prompt='Що на жінці?' AND correct_answer='Теплий светр' AND json(wrong_answers_json)=json('["Біла сорочка","Синя шапка","Червона куртка"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=4 AND prompt='Що хлопець робить після гри?' AND correct_answer='Сідає біля річки' AND json(wrong_answers_json)=json('["Іде до магазину","Читає в школі","Шукає велосипед"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=20) AND display_order=5 AND prompt='Де світить сонце в кінці?' AND correct_answer='На воді' AND json(wrong_answers_json)=json('["На книжці","На столі","На ліжку"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=22 AND title='Мій одяг' AND json(paragraphs_json)=json('["Мій одяг лежить у шафі біля ліжка. Уранці я вибираю одяг для роботи в нашому офісі. На полиці сині штани, біла сорочка і сірий светр. Я беру білу сорочку з полиці. Сірий светр теж кладу на ліжко біля сорочки.","Сьогодні холодно. На сорочку я одягаю мій улюблений сірий светр. У дзеркалі я бачу сорочку і сірий светр. Потім я одягаю куртку. Беру ключі біля дверей. До роботи я йду пішки через наш тихий парк.","Увечері я сиджу вдома на дивані з книжкою. Куртка в шафі. Мій светр має великі м''які рукави. Я п''ю теплий чай. Мої руки в теплих рукавах."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=1 AND prompt='Де лежить одяг?' AND correct_answer='У шафі' AND json(wrong_answers_json)=json('["На дивані","Під столом","У сумці"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=2 AND prompt='Де працює авторка?' AND correct_answer='В офісі' AND json(wrong_answers_json)=json('["У школі","У магазині","У парку"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=3 AND prompt='Що авторка одягає на сорочку?' AND correct_answer='Светр' AND json(wrong_answers_json)=json('["Шапку","Штани","Взуття"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=4 AND prompt='Що вона бере після куртки?' AND correct_answer='Ключі' AND json(wrong_answers_json)=json('["Книжку","Чашку","Телефон"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=22) AND display_order=5 AND prompt='Які рукави у светра?' AND correct_answer='Великі й м''які' AND json(wrong_answers_json)=json('["Малі й холодні","Нові й білі","Сині й короткі"]'))=1 THEN 1 ELSE 0 END;
INSERT INTO _a1_112_guard SELECT CASE WHEN (SELECT COUNT(*) FROM texts WHERE level='A1' AND display_order=23 AND title='Кольори навколо мене' AND json(paragraphs_json)=json('["Я щодня працюю вдома біля великого вікна моєї кімнати. Із вікна я бачу синє небо і зелене дерево. На столі стоїть біла лампа біля червоного зошита. Я пишу в зошиті кілька слів про свій день. Сестра ставить квіти у воду біля моїх книжок. Квіти жовті.","Увечері сестра ставить на мій стіл синю чашку теплого чаю. Після роботи я повільно п''ю чай біля вікна. У моїй маленькій коробці біля книжок є синій олівець. Синій — мій улюблений колір. Я беру синій олівець і малюю море на білому папері. На папері синє море."]') AND show_word_count=1)=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23))=5 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=1 AND prompt='Що автор бачить із вікна?' AND correct_answer='Небо і дерево' AND json(wrong_answers_json)=json('["Море і човен","Магазин і школу","Річку і міст"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=2 AND prompt='Яка лампа на столі?' AND correct_answer='Біла' AND json(wrong_answers_json)=json('["Синя","Зелена","Жовта"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=3 AND prompt='Які квіти біля книжок?' AND correct_answer='Жовті' AND json(wrong_answers_json)=json('["Червоні","Білі","Сині"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=4 AND prompt='Який колір автор любить?' AND correct_answer='Синій' AND json(wrong_answers_json)=json('["Білий","Жовтий","Червоний"]'))=1 AND (SELECT COUNT(*) FROM questions WHERE story_id=(SELECT id FROM texts WHERE level='A1' AND display_order=23) AND display_order=5 AND prompt='Що автор робить після чаю?' AND correct_answer='Малює море' AND json(wrong_answers_json)=json('["Пише в зошиті","Читає книжку","Готує вечерю"]'))=1 THEN 1 ELSE 0 END;
DROP TABLE _a1_112_guard;
UPDATE texts SET paragraphs_json='["Наша сім''я живе в будинку біля парку. У будинку живуть мама, тато, мій брат і я. Мама працює в школі, тато в магазині. Брат ходить у дитячий садок. Уранці всі поспішають. Ввечері ми знову разом.","На першому поверсі є кухня і вітальня. На кухні мама часто готує суп. У вітальні ми дивимося телевізор. Там стоїть диван, стіл і велика шафа. У шафі лежать книжки і настільні ігри. На другому поверсі є наші спальні.","Моя кімната невелика, але в ній є ліжко, стіл і книжки. У дворі тато ставить лавку, і влітку ми сидимо там разом. Брат грається з м''ячем, а я дивлюся на дерева. Наш дім простий, але рідний."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=1;
UPDATE texts SET paragraphs_json='["Я дуже люблю книги та іграшки. Мене звати Софійка. У моїй кімнаті є полиця з казками. Ще є велика коробка з іграшками. Я часто сиджу біля полиці після школи. Спочатку я вибираю книжку, а потім відкриваю коробку.","Щовечора я читаю коротку книжку з малюнками. Моя улюблена книжка розповідає про дівчинку і ліс. Я читаю її багато разів, бо добре знаю героїв. Я записую ім''я героя на папері. Іноді мама слухає мене і допомагає читати нові слова.","У коробці лежать кубики, лялька і маленька машина. З кубиків я будую будинок, а лялька живе в цьому будинку. Коли мама читає зі мною, я повторюю нові слова. Потім я граюся. Я вигадую маленьку історію."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=2;
UPDATE texts SET paragraphs_json='["Я живу в невеликому будинку біля саду. У будинку є чотири кімнати: кухня, спальня, вітальня і ванна кімната. Біля дверей стоїть полиця для ключів і взуття. На кухні стоїть стіл і чотири стільці. Уранці ми снідаємо там разом і говоримо про день.","У вітальні стоїть диван, низький столик і годинник на стіні. На дивані лежить теплий плед. У моїй спальні є ліжко, шафа і лампа біля ліжка. На столі лежать книжка і телефон.","Увечері я читаю у вітальні, а мама п''є чай на кухні. На вихідних я прибираю кімнату і ставлю книжки на свою полицю. Я люблю свій будинок. Він теплий і спокійний."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=3;
UPDATE texts SET paragraphs_json='["Уранці я прокидаюся. Я відкриваю вікно. У кімнаті стає свіжо і світло. Потім я вмиваюся і зачісуюся перед дзеркалом. На кухні я їм хліб із сиром і п''ю воду.","Після сніданку я йду до школи. У школі я читаю, пишу і слухаю вчителя. Після уроків я обідаю і роблю вправи. Потім я складаю книжки на стіл.","Увечері я люблю гуляти біля дому. Потім я дивлюся мультфільм, а мама готує вечерю. Я вечеряю з родиною і мию свою тарілку. Потім я рано лягаю спати."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=4;
UPDATE texts SET paragraphs_json='["У мене починаються канікули, і я не йду до школи. Уранці я довго сплю, а потім повільно снідаю. Мама готує млинці, а я п''ю чай і дивлюся у вікно.","Удень я гуляю з друзями в парку. Там є гойдалка, лавка і велика доріжка. Ми граємо в м''яч, а потім купуємо морозиво. Увечері я читаю книжку або допомагаю вдома. Я мию тарілки після обіду і складаю іграшки в коробку.","На канікулах день довгий. Я маю багато часу для гри, читання та прогулянок. У серпні ми їдемо до Одеси. Тому я дуже чекаю цю поїздку. Я хочу бачити море."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=7;
UPDATE texts SET paragraphs_json='["У мене є чудова родина. Моя мама добра і спокійна, вона готує сніданок і часто читає книжки. Мій тато веселий, він працює в офісі і любить музику.","У мене є сестра Ліза. Вона ходить до школи і любить малювати квіти. У нас є дідусь. Він часто розповідає цікаві історії. У неділю він приходить до нас на обід.","Увечері ми сидимо разом на кухні. Ми п''ємо чай, говоримо про день і сміємося. Ліза показує малюнок, тато слухає, а мама усміхається. Я дуже люблю свою родину. Коли мені потрібна допомога, родина завжди поруч. Тому вдома мені легко і тепло."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=9;
UPDATE texts SET paragraphs_json='["Сьогодні я йду на пошту, бо маю лист для тітки. Пошта стоїть біля магазину. Я кладу лист у сумку та виходжу до пошти.","На пошті працює привітна жінка. У залі тихо, і переді мною стоїть тільки один чоловік. Вона питає адресу, і я читаю її з паперу. Потім жінка бере лист, дає марку, і я плачу гроші.","Після цього я беру квитанцію і кажу: «Дякую». Біля пошти стоїть лавка, тому я сідаю на хвилину. Увечері я кажу мамі, що лист уже їде до тітки."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=10;
UPDATE texts SET paragraphs_json='["Сьогодні в наш клас приходить новий хлопець. Його звати Данило, і він сідає біля мене. Я кажу: «Привіт, мене звати Оля». Данило усміхається і відповідає: «Привіт, дуже приємно». Учитель просить нас показати Данилу розклад.","На перерві я питаю Данила, де він живе. Він каже, що живе біля парку. Потім ми говоримо про хобі. Данило любить футбол і шахи, а я люблю футбол і книжки.","Після уроків ми разом ідемо додому. Завтра ми знову сидимо поруч у класі. Він показує мені новий пенал, а я показую йому шкільний двір. Мені легко говорити з ним українською."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=12;
UPDATE texts SET paragraphs_json='["Сьогодні я їду з мамою на машині до бабусі. Мама сидить за кермом, а я сиджу поруч і тримаю квіти. У машині грає тиха музика. Дорога здається приємною. Мама питає мене про школу, і я розповідаю про уроки.","Ми їдемо через місто і бачимо магазин, аптеку та школу. Потім машина їде біля річки. Я дивлюся на воду. Мама питає, чи я маю подарунок, і я показую квіти. Я також беру маленький пиріг у коробці.","Через двадцять хвилин ми приїжджаємо. Бабуся стоїть біля воріт. Вона радіє нам. Я даю їй квіти. Мама ставить сумку на стілець, і ми сідаємо за стіл."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=13;
UPDATE texts SET paragraphs_json='["Я навчаюся в коледжі в Києві. Мене звати Максим. У понеділок я встаю о сьомій, бо заняття починається о дев''ятій. Я беру зошит, ручку, книжку і йду до школи. Біля входу я зустрічаю друга Андрія. Ми разом ідемо в клас і дивимося розклад на дверях.","Після занять я заходжу в бібліотеку. Там дуже тихо, тому я читаю текст і роблю домашнє завдання. У середу українська мова і математика, а в четвер історія. У п''ятницю ми пишемо короткий тест. Увечері я готую сумку, перевіряю олівці і заряджаю телефон. Потім я відпочиваю вдома."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=14;
UPDATE texts SET paragraphs_json='["На кухні вже сидить моя сестра. Вона ставить на стіл дві тарілки і чашки. На столі є хліб, сир і помідор. Сестра ріже хліб, а я мию помідор. Усе готове. Ми сідаємо біля вікна і бажаємо одна одній смачного.","Я їм хліб і сир та п''ю чай. Сестра теж п''є чай, але їсть помідор. За сніданком ми завжди слухаємо тиху музику. Потім я мию чашки і ставлю їх на полицю. Час іти. Я виходжу з кухні та беру сумку для роботи."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=18;
UPDATE texts SET paragraphs_json='["Уранці сонце світить у вікна нашого маленького будинку. Сьогодні в місті тепло. З вікна будинку біля парку видно синє небо. Жінка повільно веде маленьку дівчинку до річки біля парку. На жінці теплий светр, а на дівчинці біла сорочка. Поруч хлопець повільно їде на велосипеді з великим рюкзаком.","Хлопець любить грати з друзями в м''яч біля річки. Жінка з дівчинкою сидить на лавці біля старого дерева. Після гри хлопець сідає біля річки і п''є воду. Велосипед стоїть поруч. Жінка з дівчинкою тепер дивиться на воду біля лавки. На воді світить сонце."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=20;
UPDATE texts SET paragraphs_json='["У шафі біля ліжка є мій одяг. Уранці я вибираю одяг для роботи в нашому офісі. На полиці сині штани, біла сорочка і сірий светр. Я беру білу сорочку з полиці. Сірий светр теж кладу на ліжко біля сорочки.","На сорочку я одягаю мій улюблений сірий светр, бо холодно. У дзеркалі я бачу сорочку і сірий светр. Потім я одягаю куртку. Беру ключі біля дверей. До роботи я йду пішки через наш тихий парк.","Увечері я сиджу вдома на дивані з книжкою. Куртка в шафі. Мій светр має великі м''які рукави. Я п''ю теплий чай. Мої руки в теплих рукавах."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=22;
UPDATE texts SET paragraphs_json='["Я щодня працюю вдома біля великого вікна моєї кімнати. Із вікна я бачу синє небо і зелене дерево. На столі стоїть біла лампа біля червоного зошита. Я люблю писати в зошиті про свій день. Сестра ставить квіти у воду біля моїх книжок. Квіти жовті.","Увечері сестра ставить на мій стіл синю чашку теплого чаю. Після роботи я повільно п''ю чай біля вікна. У моїй маленькій коробці біля книжок є синій олівець. Синій — мій улюблений колір. Я беру синій олівець і малюю море на білому папері. На папері синє море."]',updated_at=CURRENT_TIMESTAMP WHERE level='A1' AND display_order=23;
